#!/usr/bin/env Rscript
library(BiocGenerics)
counts <- as.matrix(read.table('inputs/counts.tsv', header = TRUE, row.names = 1, check.names = FALSE))
sample_stats <- Map(function(col) {
  values <- counts[, col]
  c(sample = col, mean = mean(values), sd = sd(values))
}, colnames(counts))
result <- do.call(rbind, lapply(sample_stats, as.data.frame.list))
if (!dir.exists('outputs')) dir.create('outputs', recursive = TRUE)
write.csv(result, 'outputs/sample_stats.csv', row.names = FALSE)

#!/usr/bin/env Rscript
library(BiocParallel)

counts <- as.matrix(read.table('inputs/counts.tsv', header = TRUE, row.names = 1, check.names = FALSE))
row_means <- bpvec(seq_len(nrow(counts)), function(i) {
  rowMeans(counts[i, , drop = FALSE])
}, BPPARAM = SerialParam(progressbar = FALSE))

if (!dir.exists('outputs')) dir.create('outputs', recursive = TRUE)
row_df <- data.frame(gene = rownames(counts), mean_expression = row_means)
write.csv(row_df, 'outputs/row_means.csv', row.names = FALSE)

stats <- data.frame(
  total_genes = nrow(counts),
  min_mean = min(row_means),
  max_mean = max(row_means)
)
write.csv(stats, 'outputs/row_mean_stats.csv', row.names = FALSE)

#!/usr/bin/env Rscript
library(BiocParallel)
counts <- as.matrix(read.table('inputs/counts.tsv', header = TRUE, row.names = 1, check.names = FALSE))
row_chunks <- split(seq_len(nrow(counts)), rep(1:4, length.out = nrow(counts)))

serial_param <- SerialParam(progressbar = FALSE)
serial_res <- bplapply(row_chunks, function(idx) {
  rowSums(counts[idx, , drop = FALSE])
}, BPPARAM = serial_param)
serial_vec <- Reduce(`+`, serial_res)

multi_param <- if (.Platform$OS.type == 'windows') {
  SerialParam(progressbar = FALSE)
} else {
  workers <- min(2, parallel::detectCores())
  MulticoreParam(workers = workers, progressbar = FALSE)
}
multicore_res <- bplapply(row_chunks, function(idx) {
  rowSums(counts[idx, , drop = FALSE])
}, BPPARAM = multi_param)
multicore_vec <- Reduce(`+`, multicore_res)

diff_vec <- serial_vec - multicore_vec
comparison <- data.frame(
  sample = names(serial_vec),
  serial_sum = as.numeric(serial_vec),
  multicore_sum = as.numeric(multicore_vec),
  difference = as.numeric(diff_vec)
)

if (!dir.exists('outputs')) dir.create('outputs', recursive = TRUE)
write.csv(comparison, 'outputs/serial_vs_multicore.csv', row.names = FALSE)

meta <- data.frame(
  serial_backend = class(serial_param),
  multicore_backend = class(multi_param),
  identical = all.equal(serial_vec, multicore_vec)
)
write.csv(meta, 'outputs/backend_meta.csv', row.names = FALSE)

#!/usr/bin/env Rscript
