#!/usr/bin/env Rscript
suppressPackageStartupMessages(library(gtools))

labels <- read.csv(file.path('inputs', 'strings.csv'), stringsAsFactors = FALSE)$label
if (length(labels) == 0) stop('strings.csv is empty')
unique_labels <- unique(labels)
if (length(unique_labels) < 3) {
  unique_labels <- rep(unique_labels, length.out = 3)
}
selected <- unique_labels[seq_len(min(4, length(unique_labels)))]
perm_length <- min(3, length(selected))
perm_mat <- permutations(n = length(selected), r = perm_length, v = selected, repeats.allowed = FALSE)
if (is.null(dim(perm_mat))) {
  perm_mat <- matrix(perm_mat, ncol = perm_length, byrow = TRUE)
}
perm_df <- as.data.frame(perm_mat, stringsAsFactors = FALSE)
colnames(perm_df) <- paste0('pos', seq_len(ncol(perm_df)))

dir.create('outputs', showWarnings = FALSE, recursive = TRUE)
write.csv(perm_df, file.path('outputs', 'permutations.csv'), row.names = FALSE)

#!/usr/bin/env Rscript
suppressPackageStartupMessages(library(gtools))

values_df <- read.csv(file.path('inputs', 'values.csv'))
if (!'value' %in% names(values_df)) stop('values.csv missing value column')
values <- values_df$value
width <- min(5, length(values))
run_vals <- running(values, fun = mean, width = width, align = 'center')
run_series <- rep(NA_real_, length(values))
left_pad <- floor((width - 1) / 2)
right_pad <- width - left_pad - 1
valid_start <- 1 + left_pad
valid_end <- length(values) - right_pad
if (valid_start <= valid_end) {
  run_series[valid_start:valid_end] <- run_vals
} else {
  run_series[] <- run_vals[1]
}
output <- data.frame(index = seq_along(values), value = values, running_mean = run_series)

dir.create('outputs', showWarnings = FALSE, recursive = TRUE)
write.csv(output, file.path('outputs', 'running_mean.csv'), row.names = FALSE)

#!/usr/bin/env Rscript
suppressPackageStartupMessages(library(gtools))

values_df <- read.csv(file.path('inputs', 'values.csv'))
stopifnot('value' %in% names(values_df))
values <- values_df$value
range_min <- min(values)
range_max <- max(values)
if (range_min == range_max) {
  rescaled <- rep(0.5, length(values))
} else {
  rescaled <- (values - range_min) / (range_max - range_min)
}
result <- data.frame(value = values, rescaled = rescaled)
summary_df <- data.frame(
  metric = c('mean_raw', 'sd_raw', 'mean_rescaled', 'sd_rescaled'),
  value = c(mean(values), sd(values), mean(rescaled), sd(rescaled))
)

dir.create('outputs', showWarnings = FALSE, recursive = TRUE)
write.csv(result, file.path('outputs', 'rescaled_values.csv'), row.names = FALSE)
write.csv(summary_df, file.path('outputs', 'rescale_summary.csv'), row.names = FALSE)

