suppressPackageStartupMessages(library(survival))

# 1. 检查输入文件 / Check input files
input_path <- file.path("inputs", "BLCA.merged_only_clinical_test.txt")

if (!file.exists(input_path)) {
  stop("BLCA.merged_only_clinical_test.txt is required input")
}

# 2. 读取数据 / Read data
clin_for_surv <- read.table(input_path, header = TRUE, sep = '\t')

# 3. 提取死亡时间：取多个随访记录中的最大值 / Extract death time: take max from multiple follow-up records
ind_keep <- grep("paper_Days.until.death", colnames(clin_for_surv))
death <- as.matrix(clin_for_surv[, ind_keep])
death_collapsed <- c()
for (i in 1:dim(death)[1]) {
  if (sum(is.na(death[i,])) < dim(death)[2]) {
    m <- max(death[i,], na.rm = TRUE)
    death_collapsed <- c(death_collapsed, m)
  } else {
    death_collapsed <- c(death_collapsed, NA)
  }
}

# 4. 提取最后随访时间：同理取最大值 / Extract last follow-up time: take max similarly
ind_keep <- grep("paper_Days.to.last.followup", colnames(clin_for_surv))
fl <- as.matrix(clin_for_surv[, ind_keep])
fl_collapsed <- c()
for (i in 1:dim(fl)[1]) {
  if (sum(is.na(fl[i,])) < dim(fl)[2]) {
    m <- max(fl[i,], na.rm = TRUE)
    fl_collapsed <- c(fl_collapsed, m)
  } else {
    fl_collapsed <- c(fl_collapsed, NA)
  }
}

# 5. 合并死亡时间/随访时间 / Combine death and follow-up times
new_clin <- data.frame(death_collapsed, fl_collapsed)
colnames(new_clin) <- c('death_days', 'followUp_days')

# 6. 构建截尾生存时间 / Construct censored survival time
new_clin$new_death <- c()
for (i in 1:nrow(new_clin)) {
  death_val <- as.numeric(as.character(new_clin$death_days[i]))
  follow_val <- as.numeric(as.character(new_clin$followUp_days[i]))
  new_clin$new_death[i] <- ifelse(is.na(death_val), follow_val, death_val)
}

# 7. 构建结局事件 / Construct outcome event (1=dead, 0=alive)
new_clin$death_event <- ifelse(clin_for_surv$paper_Vital.status == "Alive", 0, 1)
rownames(new_clin) <- clin_for_surv$barcode

# 8. 创建输出目录 / Create output directory
outputs_dir <- "outputs"
dir.create(outputs_dir, showWarnings = FALSE, recursive = TRUE)

# 9. 保存结果 / Save results
saveRDS(new_clin, file.path(outputs_dir, "survival_data.rds"))
write.csv(new_clin, file.path(outputs_dir, "survival_data.csv"))

run_task <- function(work_dir) {
  expr_file <- file.path(work_dir, "inputs", "protein_expression.tsv")
  expr <- read.table(expr_file, sep="\t", header=TRUE, row.names=1)

  # Filter no missing
  expr_clean <- expr[rowSums(is.na(expr)) == 0, ]

  # Save output
  write.csv(expr_clean, file.path(work_dir, "outputs", "filtered_expression.csv"))

  return(expr_clean)
}

